<template>
	<LMap
		class="location-map"
		:style="{ height }"
		:zoom="previewZoom"
		:center="center"
		:options="{
			scrollWheelZoom: false,
			zoomControl: false,
			dragging: false,
			attributionControl: false,
		}">
		<LTileLayer :url="url" :options="tileLayerOptions" />
		<LControlAttribution
			position="bottomright"
			:prefix="attribution" />
		<LMarker :latLng="center">
			<LTooltip
				:options="{
					direction: 'top',
					permanent: 'true',
					offset: [-16, -14],
				}">
				{{ name }}
			</LTooltip>
		</LMarker>
	</LMap>
</template>

<script lang='ts'>
import {
	LControlAttribution,
	LMap,
	LMarker,
	LTileLayer,
	LTooltip,
} from '@vue-leaflet/vue-leaflet'

import 'leaflet/dist/leaflet.css'
import '../utils/leaflet-icons.ts'

export default {
	name: 'LocationMap',
	components: {
		LControlAttribution,
		LTileLayer,
		LMap,
		LMarker,
		LTooltip,
	},

	props: {
		/**
		 * The latitude of the location
		 */
		latitude: {
			type: Number,
			required: true,
		},

		/**
		 * The longitude of the location
		 */
		longitude: {
			type: Number,
			required: true,
		},

		/**
		 * Height of the map. It is set inline because the map element carries an
		 * inline height of its own, which a stylesheet cannot override.
		 */
		height: {
			type: String,
			default: '250px',
		},

		/**
		 * The name of the location
		 */
		name: {
			type: String,
			default: '',
		},
	},

	data() {
		return {
			url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
			// Nextcloud answers every request with `Referrer-Policy: no-referrer`,
			// and the tile server turns a request that carries no referrer down.
			// Setting the policy on the tiles themselves overrides that for them
			// alone, and the origin is all it hands out — the instance identifies
			// itself without telling the tile server which page of it is open.
			tileLayerOptions: { referrerPolicy: 'strict-origin-when-cross-origin' },
			// The zoom level of the map in the messages list
			previewZoom: 13,
			attribution: '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors',
		}
	},

	computed: {
		center(): [number, number] {
			return [this.latitude, this.longitude]
		},
	},
}
</script>

<style scoped lang="scss">
.location-map {
	position: relative;
	margin: 16px;
	border-radius: var(--border-radius-large);
}
</style>
